import subprocess, sys
sys.path.insert(0, "/tmp")
from mogtab import T

def consumed(name, pfx, samples):
    """Return the number of words the option consumes, or None if undetermined."""
    res = {}
    for n in range(0, 4):
        vals = [samples[k] if k < len(samples) else "zz%d" % k for k in range(n)]
        cmd = ["mogrify", pfx + name] + vals + ["nonexist.png"]
        try:
            p = subprocess.run(cmd, capture_output=True, text=True, timeout=20, cwd="/tmp/mt")
        except subprocess.TimeoutExpired:
            res[n] = "TIMEOUT"
            continue
        err = p.stderr
        if "unable to open image `nonexist.png'" in err:
            return n, res
        res[n] = (err.strip().splitlines() or [p.stdout.strip()[:60] or "rc=%d" % p.returncode])[0][:90]
    return None, res

bad = 0
for name, (m, pl, types, samples) in T.items():
    if name in ("help", "version", "list"):
        continue
    for pfx, expected in (("-", m), ("+", pl)):
        n, res = consumed(name, pfx, samples)
        if n != expected:
            bad += 1
            print("MISMATCH %s%s expected=%s got=%s %s" % (pfx, name, expected, n, res))
print("mismatches:", bad)

